/// Button/brush state; the first six map 1:1 to CommonButtonStyle NormalBase/NormalHovered/NormalPressed/SelectedBase/SelectedHovered/
/// SelectedPressed, `Disabled` to the Disabled brush (drawn with Slate's DisabledEffect permutation, as SButton does when disabled).
/// Border styles (single `Background` brush) answer every state with the same material.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum MatState { Base, Hovered, Pressed, Selected, SelectedHovered, SelectedPressed, Disabled }

impl MatState {
    pub const ALL: [MatState; 7] = [MatState::Base, MatState::Hovered, MatState::Pressed, MatState::Selected, MatState::SelectedHovered, MatState::SelectedPressed, MatState::Disabled];
    fn idx(self) -> usize { self as usize }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Draw { Image, Box }

/// Brush description of a style state (cooked FSlateBrush): `native_size` = ImageSize (Slate units), `margin` = fractions L,T,R,B of the
/// native size (Box brushes are drawn as a nine-patch: corner = margin x native size in Slate units), `tint` = brush TintColor (linear).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BrushSpec {
    pub mat: Mat,
    pub state: MatState,
    pub native_size: (f32, f32),
    pub margin: [f32; 4],
    pub tint: [f32; 4],
    pub draw: Draw,
}

/// Per-draw inputs.
#[derive(Clone, Debug)]
pub struct MatParams {
    /// Scalar material parameter `fillPercent` of OptionsSliderFill / OptionsSliderFill_Light (0..1, slider value).
    pub fill_percent: f32,
    /// View time in seconds (`cb1[131].z`): animates the shine sweep of the button materials (amplitude is 0 in the shipped instances unless
    /// the instance enables it; see reports/settings-ui-materials.json).
    pub time: f32,
    /// Widget colour & opacity multiplier (linear RGBA, white = untinted). `raster`/`raster_brush` additionally multiply the brush tint.
    pub tint: [f32; 4],
    /// Element size in Slate units used for the nine-patch margins and the `PixelSize` vertex attribute; (0,0) = use the raster `w`,`h`.
    pub size_px: (f32, f32),
    /// Engine display gamma (Fortnite Brightness setting); 2.2 = default.
    pub display_gamma: f32,
    /// Force Slate's DisabledEffect permutation on/off; `None` = on exactly for `MatState::Disabled`.
    pub disabled_effect: Option<bool>,
    /// Extra named material parameter overrides (vector or scalar-as-[v;4]), e.g. ("SelectionColor", [..]).
    pub overrides: Vec<(&'static str, V4)>,
}

impl Default for MatParams {
    fn default() -> Self {
        MatParams { fill_percent: 0.5, time: 0.0, tint: [1.0; 4], size_px: (0.0, 0.0), display_gamma: 2.2, disabled_effect: None, overrides: Vec::new() }
    }
}

