#[derive(Clone, Copy)]
struct Entry { inst: usize, draw: Draw, size: (f32, f32), margin: [f32; 4], tint: [f32; 4] }

type PsFn = fn(&[&[V4]; 3], &[V4; 12], &mut dyn FnMut(usize, f32, f32, f32) -> V4) -> V4;
type CbFn = fn(&dyn Fn(&str, V4) -> V4) -> Vec<V4>;

struct Inst {
    name: &'static str,
    /// index into PS of the Default Slate permutation / the DrawDisabledEffect permutation (usize::MAX = none)
    ps: usize,
    ps_dis: usize,
    cb: CbFn,
    params: &'static [(&'static str, V4)],
    /// texture bound to t0, t1, ... of the pixel shader (index into TEXS)
    tex: &'static [usize],
    /// the View uniform buffer is cb1 (material buffer is cb2) when true, else the material buffer is cb1
    view: bool,
}

/// `rgb: Some(c)`: every texel has this RGB (data is then the w*h alpha plane); `None`: data is w*h RGBA texels
