fn srgb_to_lin(c: f32) -> f32 { if c <= 0.04045 { c / 12.92 } else { ((c + 0.055) / 1.055).powf(2.4) } }
fn lin_to_srgb(c: f32) -> f32 { if c <= 0.0031308 { c * 12.92 } else { c.powf(1.0 / 2.4) * 1.055 - 0.055 } }

/// Slate packs the linear tint as `FLinearColor::ToFColor(true)` (sRGB bytes, floor(x*255.999)); the vertex shader decodes it back to linear
/// with the exact curve below (constants = the hex literals of the disassembled FSlateElementVS).
pub fn pack_tint(t: [f32; 4]) -> [f32; 4] {
    let mut o = [0.0f32; 4];
    for k in 0..3 {
        let byte = (lin_to_srgb(t[k].clamp(0.0, 1.0)) * 255.999).floor().clamp(0.0, 255.0) / 255.0;
        let c = byte.max(f32::from_bits(0x38800006));
        let hi = ((c * f32::from_bits(0x3f72a76e) + f32::from_bits(0x3d558919)).log2() * 2.4).exp2();
        let lo = c * f32::from_bits(0x3d9e8391);
        o[k] = if f32::from_bits(0x3d25aee6) < c { hi } else { lo };
    }
    o[3] = (t[3].clamp(0.0, 1.0) * 255.999).floor().clamp(0.0, 255.0) / 255.0;
    o
}

fn tex_texel(t: &Tex, x: i64, y: i64) -> V4 {
    let xi = if t.wrap_x { x.rem_euclid(t.w as i64) } else { x.clamp(0, t.w as i64 - 1) } as usize;
    let yi = if t.wrap_y { y.rem_euclid(t.h as i64) } else { y.clamp(0, t.h as i64 - 1) } as usize;
    let f = |c: u8| { let x = c as f32 / 255.0; if t.srgb { srgb_to_lin(x) } else { x } };
    match t.rgb {
        Some(c) => [f(c[0]), f(c[1]), f(c[2]), t.data[yi * t.w + xi] as f32 / 255.0],
        None => { let p = &t.data[(yi * t.w + xi) * 4..(yi * t.w + xi) * 4 + 4]; [f(p[0]), f(p[1]), f(p[2]), p[3] as f32 / 255.0] }
    }
}

/// Bilinear sample at texel-centre convention (sRGB texels are decoded before filtering like the GPU does).
fn tex_sample(t: &Tex, u: f32, v: f32) -> V4 {
    let (x, y) = (u * t.w as f32 - 0.5, v * t.h as f32 - 0.5);
    let (x0, y0) = (x.floor(), y.floor());
    let (fx, fy) = (x - x0, y - y0);
    let (a, b, c, d) = (tex_texel(t, x0 as i64, y0 as i64), tex_texel(t, x0 as i64 + 1, y0 as i64), tex_texel(t, x0 as i64, y0 as i64 + 1), tex_texel(t, x0 as i64 + 1, y0 as i64 + 1));
    let mut o = [0.0f32; 4];
    for k in 0..4 { o[k] = (a[k] * (1.0 - fx) + b[k] * fx) * (1.0 - fy) + (c[k] * (1.0 - fx) + d[k] * fx) * fy; }
    o
}

struct Ctx { inst: &'static Inst, cb0: Vec<V4>, view: Vec<V4>, mat: Vec<V4>, size: (f32, f32) }

fn make_ctx(inst_idx: usize, p: &MatParams, size: (f32, f32)) -> Ctx {
    let inst = &INSTS[inst_idx];
    let lookup = |name: &str, default: V4| -> V4 {
        for (n, v) in p.overrides.iter().rev() { if *n == name { return *v; } }
        if name == "fillPercent" { return [p.fill_percent; 4]; }
        for (n, v) in inst.params.iter() { if *n == name { return *v; } }
        default
    };
    let g = p.display_gamma.max(0.01);
    let mut view = vec![[0.0f32; 4]; 132];
    view[131] = [0.0, 0.0, p.time, 0.0];
    Ctx { inst, cb0: vec![[0.0; 4], [0.0; 4], [2.2 / g, 1.0 / g, 0.0, 0.0]], view, mat: (inst.cb)(&lookup), size }
}

/// Run the cooked pixel shader once. `uv_mat` = MaterialTexCoords (TexCoord0, linear 0..1 over the element), `uv_brush` = TextureCoordinates.xy (the brush uv:
/// nine-patch mapped for Box brushes with a margin, else linear), `tint` = LINEAR vertex colour (already unpacked).
fn shade_ctx(c: &Ctx, disabled: bool, uv_mat: [f32; 2], uv_brush: [f32; 2], tint: [f32; 4]) -> V4 {
    let mut v = [[0.0f32; 4]; 12];
    v[1] = tint;
    v[6] = [uv_brush[0], uv_brush[1], 1.0, 1.0];
    v[7] = [0.0, 0.0, c.size.0, c.size.1];
    v[8] = [uv_mat[0], uv_mat[1], 0.0, 0.0];
    let cbs: [&[V4]; 3] = if c.inst.view { [&c.cb0, &c.view, &c.mat] } else { [&c.cb0, &c.mat, &c.mat] };
    let inst = c.inst;
    let mut tex = |slot: usize, u: f32, vv: f32, _lod: f32| -> V4 { tex_sample(&TEXS[inst.tex[slot]], u, vv) };
    let f = if disabled && inst.ps_dis != usize::MAX { PS[inst.ps_dis] } else { PS[inst.ps] };
    f(&cbs, &v, &mut tex)
}

fn entry(mat: Mat, state: MatState) -> Option<Entry> { TABLE[mat as usize][state.idx()] }

fn to_spec(mat: Mat, state: MatState, e: &Entry) -> BrushSpec {
    BrushSpec { mat, state, native_size: e.size, margin: e.margin, tint: e.tint, draw: e.draw }
}

/// The cooked brush Slate uses for `mat` in `state` (None = NoDrawType / nothing drawn).
pub fn default_brush(mat: Mat, state: MatState) -> Option<BrushSpec> { entry(mat, state).map(|e| to_spec(mat, state, &e)) }

/// Brush of a style asset (`"ButtonStyle-Tab-Manage"`, `"/Game/UI/.../Border-MainL"`, ...) for a state; None for NoDrawType brushes / unknown styles.
pub fn brush_of(style: &str, state: MatState) -> Option<BrushSpec> {
    let s = style.rsplit('/').next().unwrap_or(style);
    let s = s.split('.').next().unwrap_or(s);
    for (name, mat) in STYLE_NAMES.iter() { if *name == s { return default_brush(*mat, state); } }
    None
}

impl Mat {
    pub fn style(self) -> Option<&'static str> { STYLE_OF[self as usize] }
}

/// Slate nine-patch (AddBoxElement): maps an element-local position (Slate units, 0..size) to the uv the vertices carry.
/// Corners are `margin x native_size` Slate units (scaled down proportionally when the element is smaller than both margins together);
/// the stretched middle patch spans uv margin_l .. 1-margin_r. Zero margins give a plain 0..1 stretch.
pub fn nine_slice_uv(pos: (f32, f32), size: (f32, f32), native: (f32, f32), margin: [f32; 4]) -> [f32; 2] {
    fn axis(p: f32, size: f32, native: f32, m0: f32, m1: f32) -> f32 {
        let (mut a, mut b) = (m0 * native, m1 * native);
        if a + b > size && a + b > 0.0 { let s = size / (a + b); a *= s; b *= s; }
        if p < a { if a > 0.0 { p / a * m0 } else { 0.0 } }
        else if p > size - b { if b > 0.0 { (1.0 - m1) + (p - (size - b)) / b * m1 } else { 1.0 } }
        else { let w = size - a - b; if w > 0.0 { m0 + (p - a) / w * (1.0 - m0 - m1) } else { m0 } }
    }
    [axis(pos.0, size.0, native.0, margin[0], margin[2]), axis(pos.1, size.1, native.1, margin[1], margin[3])]
}

fn raster_entry(e: &Entry, mat: Mat, state: MatState, w: u32, h: u32, p: &MatParams) -> Vec<u8> {
    let (w, h) = (w.max(1), h.max(1));
    let size = if p.size_px.0 > 0.0 && p.size_px.1 > 0.0 { p.size_px } else { (w as f32, h as f32) };
    let ctx = make_ctx(e.inst, p, size);
    let disabled = p.disabled_effect.unwrap_or(state == MatState::Disabled);
    let tint = pack_tint([p.tint[0] * e.tint[0], p.tint[1] * e.tint[1], p.tint[2] * e.tint[2], p.tint[3] * e.tint[3]]);
    let boxed = e.draw == Draw::Box && e.margin.iter().any(|m| *m != 0.0);
    let mut out = vec![0u8; (w * h * 4) as usize];
    for y in 0..h {
        for x in 0..w {
            let lin = [(x as f32 + 0.5) / w as f32, (y as f32 + 0.5) / h as f32];
            let uv_brush = if boxed { nine_slice_uv((lin[0] * size.0, lin[1] * size.1), size, e.size, e.margin) } else { lin };
            let c = shade_ctx(&ctx, disabled, lin, uv_brush, tint);
            let o = ((y * w + x) * 4) as usize;
            for k in 0..4 { out[o + k] = (c[k].clamp(0.0, 1.0) * 255.0 + 0.5) as u8; }
        }
    }
    out
}

/// Straight-alpha RGBA8 image (NOT premultiplied) of the cooked material of `mat` in `state`, drawn into `w` x `h` pixels the way Slate draws the
/// style's brush (nine-patch uv mapping for Box brushes with a margin, brush tint x `p.tint`); RGB is already in the presented (sRGB) space.
/// States without a drawn brush (NoDrawType) return a fully transparent image. Deterministic.
pub fn raster(mat: Mat, state: MatState, w: u32, h: u32, p: &MatParams) -> Vec<u8> {
    match entry(mat, state) {
        Some(e) => raster_entry(&e, mat, state, w, h, p),
        None => vec![0u8; (w.max(1) * h.max(1) * 4) as usize],
    }
}

/// Like `raster` but with an explicit brush (e.g. from `brush_of`, or a hand-edited margin/size/tint); the brush tint multiplies `p.tint`.
pub fn raster_brush(b: &BrushSpec, w: u32, h: u32, p: &MatParams) -> Vec<u8> {
    match entry(b.mat, b.state) {
        Some(e0) => { let e = Entry { inst: e0.inst, draw: b.draw, size: b.native_size, margin: b.margin, tint: b.tint }; raster_entry(&e, b.mat, b.state, w, h, p) }
        None => vec![0u8; (w.max(1) * h.max(1) * 4) as usize],
    }
}

/// One shaded sample (straight RGBA, 0..1, presented space) with explicit shader inputs: `uv_mat` = TexCoord0 (linear over the element),
/// `uv_brush` = brush uv (TexCoords.xy, nine-patch mapped for Box brushes), `size` = element size in Slate units (PixelSize).
pub fn shade_uv(mat: Mat, state: MatState, uv_mat: [f32; 2], uv_brush: [f32; 2], size: (f32, f32), p: &MatParams) -> Option<[f32; 4]> {
    let e = entry(mat, state)?;
    let ctx = make_ctx(e.inst, p, size);
    let tint = pack_tint([p.tint[0] * e.tint[0], p.tint[1] * e.tint[1], p.tint[2] * e.tint[2], p.tint[3] * e.tint[3]]);
    Some(shade_ctx(&ctx, p.disabled_effect.unwrap_or(state == MatState::Disabled), uv_mat, uv_brush, tint))
}

/// One shaded sample at element-local position `pos` (Slate units, 0..size): derives both uv sets exactly like `raster` does for a pixel centre.
pub fn shade_pos(mat: Mat, state: MatState, pos: (f32, f32), size: (f32, f32), p: &MatParams) -> Option<[f32; 4]> {
    let e = entry(mat, state)?;
    let lin = [pos.0 / size.0, pos.1 / size.1];
    let boxed = e.draw == Draw::Box && e.margin.iter().any(|m| *m != 0.0);
    let uv_brush = if boxed { nine_slice_uv(pos, size, e.size, e.margin) } else { lin };
    shade_uv(mat, state, lin, uv_brush, size, p)
}

/// The evaluated material uniform buffer (what the cooked pixel shader reads from its material cbuffer) of `mat` in `state`, e.g. for a GPU port.
pub fn material_uniforms(mat: Mat, state: MatState, p: &MatParams) -> Option<Vec<[f32; 4]>> {
    let e = entry(mat, state)?;
    Some(make_ctx(e.inst, p, (1.0, 1.0)).mat)
}

/// Name of the cooked material instance that draws `mat` in `state`.
pub fn material_name(mat: Mat, state: MatState) -> Option<&'static str> { entry(mat, state).map(|e| INSTS[e.inst].name) }


// D3D bit-mask helpers used by the translated shaders (comparisons yield 0xFFFFFFFF / 0, movc tests for non-zero bits)
#[inline] fn m(c: bool) -> f32 { f32::from_bits(if c { 0xFFFF_FFFF } else { 0 }) }
#[inline] fn nz(x: f32) -> bool { x.to_bits() != 0 }
#[inline] fn sat(x: f32) -> f32 { x.max(0.0).min(1.0) }
fn round_ne(x: f32) -> f32 { let r = x.round(); if (x - x.trunc()).abs() == 0.5 && r % 2.0 != 0.0 { r - x.signum() } else { r } }
fn vadd(a: V4, b: V4) -> V4 { [a[0] + b[0], a[1] + b[1], a[2] + b[2], a[3] + b[3]] }
fn vsub(a: V4, b: V4) -> V4 { [a[0] - b[0], a[1] - b[1], a[2] - b[2], a[3] - b[3]] }
fn vmul(a: V4, b: V4) -> V4 { [a[0] * b[0], a[1] * b[1], a[2] * b[2], a[3] * b[3]] }
fn vdiv(a: V4, b: V4) -> V4 { let d = |x: f32, y: f32| if y == 0.0 { 0.0 } else { x / y }; [d(a[0], b[0]), d(a[1], b[1]), d(a[2], b[2]), d(a[3], b[3])] }
